#!/usr/bin/env python3
"""Verify current generated byte arrays against the retained matching firmware ELF.

Run in the ESP-IDF Python environment (pyelftools). This also detects an older
build/asset mismatch; it does not replace the repository's merged-image verifier.
"""
import argparse
import re
import struct
from pathlib import Path
from elftools.elf.elffile import ELFFile

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('elf', type=Path)
args = parser.parse_args()
root = Path(__file__).resolve().parent.parent
with args.elf.open('rb') as f:
    elf = ELFFile(f)
    symbols = {s.name: s for s in elf.get_section_by_name('.symtab').iter_symbols()}

    def embedded(name):
        symbol = symbols[name]
        section = elf.get_section(symbol['st_shndx'])
        offset = symbol['st_value']-section['sh_addr']
        return section.data()[offset:offset+symbol['st_size']]

    unused = {"pixels_cockpit", "pixels_asphalt", "pixels_glass", "pixels_logo"}
    count = 0
    total = 0
    for name in ['assets/images/brake-hero/converted/brake_images.c', 'assets/music/brake-hero/brake_audio.c']:
        source = (root/name).read_text()
        for symbol, body in re.findall(r'const uint8_t (\w+)\[\] = \{([\d,\s]+)\};', source):
            expected = bytes(int(n) for n in re.findall(r'\d+', body))
            if symbol not in symbols:
                assert symbol in unused, f"Missing required asset: {symbol}"
                continue
            assert embedded(symbol) == expected, f'{symbol}: current source differs from firmware'
            count += 1; total += len(expected)
    assert count == 24, count
    source = (root/'assets/fonts/brake-hero/brake_font.c').read_text()
    glyphs = []
    for codepoint, width, body in re.findall(r'\{(\d+),(\d+),\{([\d,]+)\}\}', source):
        glyphs.append(struct.pack('<IB28s3x', int(codepoint), int(width), bytes(map(int, body.split(',')))))
    assert len(glyphs) >= 266
    assert embedded('bh_glyphs') == b''.join(glyphs), 'Current font differs from firmware'
    assert embedded('bh_glyph_count') == struct.pack('<I', len(glyphs))
print(f'Current generated assets match retained firmware ELF: PASS ({count} byte arrays, {total} bytes, {len(glyphs)} glyphs)')
